    "      final attributeOffset = offset + rawName.length - attributeName.length;\n"
    "      final spreadMap = attributeName.startsWith('...')\n"
    "          ? attributeName.substring('...'.length)\n"
    "          : null;\n"
    "      final spreadMapOffset = attributeOffset + '...'.length;\n"
    "      if (spreadMap != null) {\n"
    "        if (match[0]!.length != rawName.length) {\n"
    "          fail(\n"
    "            '\"\$attributeName\" takes no value; it writes every entry of the '\n"
    "            'Map<String, String> as an attribute, like \$_spreadAttributeUsage',\n"
    "            offset,\n"
    "          );\n"
    "        }\n"
    "        requireValuePath(spreadMap, spreadMapOffset, '\"...attributes\"');\n"
    "      } else if (plainAttributeNames.contains(attributeName.toLowerCase())) {\n"
    "        // Conditional ones may share a name: each condition picks one value.\n"
    "        fail(\n"
    "          '\"\$attributeName\" is also a plain attribute in this tag and '\n"
    "          'browsers keep only the first; compute one value in Dart and pass '\n"
    "          'it in',\n"
    "          offset,\n"
    "        );\n"
    "      }\n"
    "      var whitespaceStart = offset;\n"
    "      while (whitespaceStart > textStart &&\n"
    "          source[whitespaceStart - 1].trim().isEmpty) {\n"
    "        whitespaceStart--;\n"
    "      }\n"
    "      writeTextWithInterpolations(textStart, whitespaceStart);\n"
    "      flushText();\n"
    "      if (condition != null) {\n"
    "        emit('if (\$negation\$condition) {', sourceOffset: conditionOffset);\n"
    "        indentLevel++;\n"
    "      }\n"
    "      if (spreadMap != null) {\n"
    "        // _\$writeAttributes puts a space before each entry, so an empty map\n"
    "        // leaves no gap.\n"
    "        emit(\n"
    "          '_\\\$writeAttributes(\\\$out, \$spreadMap, \$writtenNamesVariable);',\n"
    "          sourceOffset: spreadMapOffset,\n"
    "        );\n"
    "      } else {\n"
    "        if (writtenNamesVariable != null) {\n"
    "          emit(\n"
    "            '_\\\$addConditionalAttributeName(\$writtenNamesVariable, '\n"
    "            '\${_dartStringLiteral(attributeName.toLowerCase())});',\n"
    "          );\n"
    "        }\n"
    "        pendingText.write(source.substring(whitespaceStart, offset));\n"
    "        pendingText.write(attributeName);\n"
    "        writeTextWithInterpolations(\n"
    "          offset + rawName.length,\n"
    "          offset + match.end - match.start,\n"
    "        );\n"
    "        flushText();\n"
    "      }\n"
    "      if (condition != null) {\n"
    "        indentLevel--;\n"
    "        emit('}');\n"
    "      }\n"
    "      textStart = offset + match.end - match.start;\n"
    "    }\n"
    "    writeTextWithInterpolations(textStart, tagEnd);\n"
    "  }\n"
    "\n"
    "  /// Writes the text from [start] to [end], failing on a `...attributes`\n"
    "  /// that only works inside an HTML tag. Code in `<script>` and `<style>`\n"
    "  /// may spread its own variables.\n"
    "  void writeText(int start, int end) {\n"
    "    if (start >= rawTextEnd) {\n"
    "      for (final spread in _spreadInTextPattern.allMatches(\n"
    "        source.substring(start, end),\n"
    "      )) {\n"
    "        if (variablesInScope.contains(spread[1])) {\n"
    "          fail(\n"
    "            '\"\${spread[0]}\" only works inside an HTML tag, like '\n"
    "            '<div \${spread[0]}>; here it would render as text',\n"
    "            start + spread.start,\n"
    "          );\n"
    "        }\n"
    "      }\n"
    "    }\n"
    "    pendingText.write(source.substring(start, end));\n"
    "  }\n"
    "\n"
    "  while (true) {\n"
    "    // An open <x-fragment> holds only <x-slot> tags and whitespace.\n"
    "    if (openDirectives.lastOrNull?.name == 'fragment') {\n"
    "      position = _leadingWhitespacePattern.matchAsPrefix(source, position)!.end;\n"
    "      if (position < source.length &&\n"
    "          !source.startsWith('<x-slot', position) &&\n"
    "          !source.startsWith('</x-fragment', position)) {\n"
    "        fail(\n"
    "          '<x-fragment> can only contain <x-slot> tags; put content in a '\n"
    "          'slot, like \$_slotUsage',\n"
    "          position,\n"
    "        );\n"
    "      }\n"
    "    }\n"
    "    final match = _directiveStartPattern\n"
    "        .allMatches(source, position)\n"
    "        .firstOrNull;\n"
    "    if (match == null) {\n"
    "      writeText(position, source.length);\n"
    "      break;\n"
    "    }\n"
    "    writeText(position, match.start);\n"
    "    final offset = match.start;\n"
    "\n"
    "    switch (match[0]) {\n"
    "      case '<!--':\n"
    "        final end = source.indexOf('-->', match.end);\n"
    "        if (end == -1) {\n"
    "          fail('HTML comment \"<!--\" is never closed with \"-->\"', offset);\n"
    "        }\n"
    "        pendingText.write(source.substring(offset, end + 3));\n"
    "        position = end + 3;\n"
    "\n"
    "      case '{{':\n"
    "        // HTML escaping does not make a value safe as code.\n"
    "        if (offset < rawTextEnd) {\n"
    "          fail(\n"
    "            '\"{{ }}\" cannot go inside <script> or <style>, where HTML '\n"
    "            'escaping does not make values safe; put the value in a quoted '\n"
    "            'data- attribute, like <div data-name=\"{{ name }}\">, and read it '\n"
    "            'from the script',\n"
    "            offset,\n"
    "          );\n"
    "        }\n"
    "        position = writeInterpolation(offset, source.length);\n"
    "\n"
    "      case '<':\n"
    "        final tagEnd = offset < rawTextEnd ? null : htmlTagEnd(offset);\n"
    "        if (tagEnd == null) {\n"
    "          pendingText.write('<');\n"
    "          position = offset + 1;\n"
    "        } else {\n"
    "          writeHtmlTag(offset, tagEnd);\n"
    "          position = tagEnd;\n"
    "          final tagName = _htmlTagNamePattern.matchAsPrefix(\n"
    "            source,\n"
    "            offset,\n"
    "          )![0]!;\n"
    "          if (_rawTextOpeningTagNamePattern.hasMatch(tagName)) {\n"
    "            rawTextEnd =\n"
    "                _rawTextClosingTagPattern\n"
    "                    .allMatches(source, tagEnd)\n"
    "                    .firstOrNull\n"
    "                    ?.start ??\n"
    "                source.length;\n"
    "          }\n"
    "        }\n"
    "\n"
    "      case '</x-':\n"
    "        final tag =\n"
    "            _closeTagPattern.matchAsPrefix(source, offset) ??\n"
    "            fail(\n"
    "              'malformed closing tag; expected </x-for>, </x-if>, '\n"
    "              '</x-if-not>, </x-fragment> or </x-slot>',\n"
    "              offset,\n"
    "            );\n"
    "        final innermost = openDirectives.lastOrNull;\n"
    "        if (innermost == null) {\n"
    "          fail('</x-\${tag[1]}> has no matching <x-\${tag[1]}>', offset);\n"
    "        }\n"
    "        if (innermost.name != tag[1]) {\n"
    "          fail(\n"
    "            '</x-\${tag[1]}> found while <x-\${innermost.name}> from line '\n"
    "            '\${locate(innermost.offset).line} is still open; '\n"
    "            'close it with </x-\${innermost.name}> first',\n"
    "            offset,\n"
    "          );\n"
    "        }\n"
    "        position = positionAfterDirectiveTag(offset, tag.end);\n"
    "        flushText();\n"
    "        openDirectives.removeLast();\n"
    "        variablesInScope.length -= innermost.variableCount;\n"
    "        if (innermost.indexVariable case final indexVariable?) {\n"
    "          emit('\$indexVariable++;', sourceOffset: innermost.offset);\n"
    "          indentLevel--;\n"
    "          emit('}');\n"
    "        }\n"
    "        indentLevel--;\n"
    "        switch (innermost.name) {\n"
    "          case 'fragment':\n"
    "            argumentNamesOfOpenFragments.removeLast();\n"
    "            emit('));', sourceOffset: innermost.offset);\n"
    "          case 'slot':\n"
    "            emit('}),');\n"
    "          default:\n"
    "            emit('}');\n"
    "        }\n"
    "\n"
    "      default:\n"
    "        final tag =\n"
    "            _openTagPattern.matchAsPrefix(source, offset) ??\n"
    "            fail(\n"
    "              'malformed <x-...> tag; check that the directive name is '\n"
    "              'lowercase, every attribute value is quoted and the tag ends '\n"
    "              'with \">\"',\n"
    "              offset,\n"
    "            );\n"
    "        final tagName = tag[1]!;\n"
    "        final attributes = _parseAttributes(\n"
    "          tag[2]!,\n"
    "          offset + '<x-'.length + tagName.length,\n"
    "          fail,\n"
    "        );\n"
    "        for (final MapEntry(key: name, value: attribute)\n"
    "            in attributes.entries) {\n"
    "          if (_spreadAttributeNamePattern.hasMatch(name)) {\n"
    "            fail(\n"
    "              '\"\$name\" only works on HTML tags, not on <x-\$tagName>; '\n"
    "              '\${tagName == 'fragment' ? 'give the template a Map<String, String> prop and pass the map to it as one' : 'put it on the HTML tag inside'}',\n"
    "              attribute.offset,\n"
    "            );\n"
    "          }\n"
    "        }\n"
    "        final isSelfClosing = tag[3]!.isNotEmpty;\n"
    "        if (tagName != 'fragment' && isSelfClosing) {\n"
    "          fail(\n"
    "            '<x-\$tagName> cannot end with />; close it with </x-\$tagName>',\n"
    "            offset,\n"
    "          );\n"
    "        }\n"
    "        position = tag.end;\n"
    "\n"
    "        switch (tagName) {\n"
    "          case 'props':\n"
    "            if (source.substring(0, offset).trim().isNotEmpty) {\n"
    "              fail(\n"
    "                '<x-props> must be the first thing in the template; only '\n"
    "                'whitespace may come before it',\n"
    "                offset,\n"
    "              );\n"
    "            }\n"
    "            final closeTag = _closeTagPattern.matchAsPrefix(\n"
    "              source,\n"
    "              _leadingWhitespacePattern.matchAsPrefix(source, position)!.end,\n"
    "            );\n"
    "            if (closeTag == null || closeTag[1] != 'props') {\n"
    "              fail(\n"
    "                '<x-props> must be closed right away with </x-props>; '\n"
    "                'it cannot contain content',\n"
    "                offset,\n"
    "              );\n"
    "            }\n"
    "            final declarations = [\n"
    "              for (final MapEntry(key: name, value: attribute)\n"
    "                  in attributes.entries)\n"
    "                if (!_isValidName(name))\n"
    "                  fail(\n"
    "                    '\"\$name\" is not a valid parameter name; \$_nameRules',\n"
    "                    attribute.offset,\n"
    "                  )\n"
    "                else if (attribute.value?.contains('&') ?? false)\n"
    "                  fail(\n"
    "                    'write the type of \"\$name\" as plain Dart, such as '\n"
    "                    'List<String>; HTML entities like &lt; are not decoded',\n"
    "                    attribute.offset,\n"
    "                  )\n"
    "                else if (attribute.value?.trim() case final type?\n"
    "                    when type.isNotEmpty)\n"
    "                  '    \${type.endsWith('?') ? '' : 'required '}\$type \$name, '\n"
    "                      '\${sourceMarker(attribute.offset)}'\n"
    "                else\n"
    "                  fail(\n"
    "                    'parameter \"\$name\" needs a Dart type, e.g. \$name=\"String\"',\n"
    "                    attribute.offset,\n"
    "                  ),\n"
    "            ];\n"
    "            variablesInScope.addAll(attributes.keys);\n"
    "            if (declarations.isNotEmpty) {\n"
    "              parameters = '{\\n\${declarations.join('\\n')}\\n  }';\n"
    "            }\n"
    "            pendingText.clear();\n"
    "            position = _leadingWhitespacePattern\n"
    "                .matchAsPrefix(source, closeTag.end)!\n"
    "                .end;\n"
    "\n"
    "          case 'for':\n"
    "            position = positionAfterDirectiveTag(offset, tag.end);\n"
    "            flushText();\n"
    "            rejectUnknownAttributes(attributes, 'for', const [\n"
    "              'in',\n"
    "              'as',\n"
    "              'indexed',\n"
    "              'index-as',\n"
    "            ]);\n"
    "            final iterable = requiredAttribute(\n"
    "              attributes,\n"
    "              'in',\n"
    "              directive: 'for',\n"
    "              usage: _forUsage,\n"
    "              tagOffset: offset,\n"
    "            );\n"
    "            final itemVariable = variableAttribute(\n"
    "              attributes,\n"
    "              'as',\n"
    "              tagOffset: offset,\n"
    "            );\n"
    "            String? indexVariable;\n"
    "            int? start;\n"
    "            if (attributes.containsKey('indexed') ||\n"
    "                attributes.containsKey('index-as')) {\n"
    "              final indexed = requiredAttribute(\n"
    "                attributes,\n"
    "                'indexed',\n"
    "                directive: 'for',\n"
    "                usage: _forUsage,\n"
    "                tagOffset: offset,\n"
    "              );\n"
    "              start =\n"
    "                  int.tryParse(indexed.value) ??\n"
    "                  fail(\n"
    "                    '\"indexed\" must be an integer such as 0 or 1, '\n"
    "                    'got \"\${indexed.value}\"',\n"
    "                    indexed.offset,\n"
    "                  );\n"
    "              indexVariable = variableAttribute(\n"
    "                attributes,\n"
    "                'index-as',\n"
    "                tagOffset: offset,\n"
    "              );\n"
    "              if (indexVariable == itemVariable) {\n"
    "                fail(\n"
    "                  '\"index-as\" and \"as\" must name different variables, '\n"
    "                  'both are \"\$indexVariable\"',\n"
    "                  attributes['index-as']!.offset,\n"
    "                );\n"
    "              }\n"
    "            }\n"
    "            requireValuePath(iterable.value, iterable.offset, '\"in\"');\n"
    "            if (indexVariable != null) {\n"
    "              emit('{');\n"
    "              indentLevel++;\n"
    "              emit('var \$indexVariable = \$start;', sourceOffset: offset);\n"
    "            }\n"
    "            emit(\n"
    "              'for (final \$itemVariable in (\${iterable.value})) {',\n"
    "              sourceOffset: iterable.offset,\n"
    "            );\n"
    "            indentLevel++;\n"
    "            final loopVariables = [itemVariable, ?indexVariable];\n"
    "            variablesInScope.addAll(loopVariables);\n"
    "            openDirectives.add((\n"
    "              name: 'for',\n"
    "              indexVariable: indexVariable,\n"
    "              offset: offset,\n"
    "              variableCount: loopVariables.length,\n"
    "            ));\n"
    "\n"
    "          case 'if' || 'if-not':\n"
    "            position = positionAfterDirectiveTag(offset, tag.end);\n"
    "            flushText();\n"
    "            rejectUnknownAttributes(attributes, tagName, const ['case']);\n"
    "            final condition = requiredAttribute(\n"
    "              attributes,\n"
    "              'case',\n"
    "              directive: tagName,\n"
    "              usage: tagName == 'if' ? _ifUsage : _ifNotUsage,\n"
    "              tagOffset: offset,\n"
    "            );\n"
    "            requireValuePath(condition.value, condition.offset, '\"case\"');\n"
    "            final negation = tagName == 'if' ? '' : '!';\n"
    "            emit(\n"
    "              'if (\$negation\${condition.value}) {',\n"
    "              sourceOffset: condition.offset,\n"
    "            );\n"
    "            indentLevel++;\n"
    "            openDirectives.add((\n"
    "              name: tagName,\n"
    "              indexVariable: null,\n"
    "              offset: offset,\n"
    "              variableCount: 0,\n"
    "            ));\n"
    "\n"
    "          case 'fragment':\n"
    "            final fragmentPath = requiredAttribute(\n"
    "              attributes,\n"
    "              '_',\n"
    "              directive: 'fragment',\n"
    "              usage: _fragmentUsage,\n"
    "              tagOffset: offset,\n"
    "            );\n"
    "            if (!fragmentPath.value.startsWith('/') ||\n"
    "                !fragmentPath.value.endsWith('.html')) {\n"
    "              fail(\n"
    "                '\"_\" must be the path of a template from the input '\n"
    "                'directory, starting with / and ending with .html, like '\n"
    "                '\"/ui/label.html\"; got \"\${fragmentPath.value}\"',\n"
    "                fragmentPath.offset,\n"
    "              );\n"
    "            }\n"
    "            final renderedTemplatePath = fragmentPath.value.substring(1);\n"
    "            final accessPath = accessPathByTemplatePath == null\n"
    "                ? ''\n"
    "                : accessPathByTemplatePath[renderedTemplatePath] ??\n"
    "                      fail(\n"
    "                        'there is no template \${fragmentPath.value} in the '\n"
    "                        'input directory',\n"
    "                        fragmentPath.offset,\n"
    "                      );\n"
    "            final arguments = [\n"
    "              for (final MapEntry(key: name, value: attribute)\n"
    "                  in attributes.entries)\n"
    "                if (name != '_')\n"
    "                  '\$name: \${fragmentArgument(name, attribute)}, '\n"
    "                      '\${sourceMarker(attribute.offset)}',\n"
    "            ];\n"
    "            flushText();\n"
    "            emit('_\\\$write(\\\$out, \$accessPath(', sourceOffset: offset);\n"
    "            indentLevel++;\n"
    "            arguments.forEach(emit);\n"
    "            if (isSelfClosing) {\n"
    "              indentLevel--;\n"
    "              emit('));', sourceOffset: offset);\n"
    "            } else {\n"
    "              argumentNamesOfOpenFragments.add(attributes.keys.toSet());\n"
    "              openDirectives.add((\n"
    "                name: 'fragment',\n"
    "                indexVariable: null,\n"
    "                offset: offset,\n"
    "                variableCount: 0,\n"
    "              ));\n"
    "            }\n"
    "            final location = locate(offset);\n"
    "            renderedFragments.add((\n"
    "              templatePath: renderedTemplatePath,\n"
    "              line: location.line,\n"
    "              column: location.column,\n"
    "              lineText: location.lineText,\n"
    "            ));\n"
    "\n"
    "          case 'slot':\n"
    "            if (openDirectives.lastOrNull?.name != 'fragment') {\n"
    "              fail(\n"
    "                '<x-slot> only goes directly inside <x-fragment>, like '\n"
    "                '\$_slotUsage',\n"
    "                offset,\n"
    "              );\n"
    "            }\n"
    "            rejectUnknownAttributes(attributes, 'slot', const ['name']);\n"
    "            final slotName = requiredAttribute(\n"
    "              attributes,\n"
    "              'name',\n"
    "              directive: 'slot',\n"
    "              usage: _slotUsage,\n"
    "              tagOffset: offset,\n"
    "            );\n"
    "            if (!_isValidName(slotName.value)) {\n"
    "              fail(\n"
    "                '\"\${slotName.value}\" is not a valid prop name; \$_nameRules',\n"
    "                slotName.offset,\n"
    "              );\n"
    "            }\n"
    "            if (!argumentNamesOfOpenFragments.last.add(slotName.value)) {\n"
    "              fail(\n"
    "                'prop \"\${slotName.value}\" is already passed to this '\n"
    "                '<x-fragment>; pass each prop once',\n"
    "                slotName.offset,\n"
    "              );\n"
    "            }\n"
    "            position = positionAfterDirectiveTag(offset, tag.end);\n"
    "            emit(\n"
    "              '\${slotName.value}: Fragment._((\\\$out) {',\n"
    "              sourceOffset: slotName.offset,\n"
    "            );\n"
    "            indentLevel++;\n"
    "            openDirectives.add((\n"
    "              name: 'slot',\n"
    "              indexVariable: null,\n"
    "              offset: offset,\n"
    "              variableCount: 0,\n"
    "            ));\n"
    "\n"
    "          default:\n"
    "            fail(\n"
    "              '<x-\$tagName> is not a directive; supported directives are '\n"
    "              '<x-props>, <x-for>, <x-if>, <x-if-not>, <x-fragment> and '\n"
    "              '<x-slot>',\n"
    "              offset,\n"
    "            );\n"
    "        }\n"
    "    }\n"
    "  }\n"
    "\n"
    "  if (openDirectives.lastOrNull case final unclosed?) {\n"
    "    fail(\n"
    "      '<x-\${unclosed.name}> is never closed; add </x-\${unclosed.name}>',\n"
    "      unclosed.offset,\n"
    "    );\n"
    "  }\n"
    "  flushText();\n"
    "  return (\n"
    "    parameters: parameters,\n"
    "    body: body.toString(),\n"
    "    renderedFragments: renderedFragments,\n"
    "  );\n"
    "}\n"
    "\n"
    "bool _isValidName(String name) =>\n"
    "    _identifierPattern.hasMatch(name) && !reservedDartNames.contains(name);\n"
    "\n"
    "/// Parses the attributes of a tag; [sourceOffset] is where [source] starts\n"
    "/// in the template, so each attribute knows its offset (its value's, if any).\n"
    "Map<String, _Attribute> _parseAttributes(\n"
    "  String source,\n"
    "  int sourceOffset,\n"
    "  Never Function(String, int) fail,\n"
    ") {\n"
    "  final attributes = <String, _Attribute>{};\n"
    "  for (final match in _attributePattern.allMatches(source)) {\n"
    "    final name = match[1]!;\n"
    "    final nameOffset = sourceOffset + match.start;\n"
    "    if (attributes.containsKey(name)) {\n"
    "      fail('attribute \"\$name\" is declared twice', nameOffset);\n"
    "    }\n"
    "    // Unquoted, the spaces in {{ name }} would split it into three attributes.\n"
    "    if (match[4]?.startsWith('{{') ?? false) {\n"
    "      fail('quote {{ }} values, like \$name=\"{{ \$name }}\"', nameOffset);\n"
    "    }\n"
    "    final rawValue = match[2] ?? match[3] ?? match[4];\n"
    "    attributes[name] = rawValue == null\n"
    "        ? (value: null, offset: nameOffset)\n"
    "        : (\n"
    "            value: rawValue,\n"
    "            offset:\n"
    "                nameOffset +\n"
    "                match[0]!.indexOf(rawValue, match[0]!.indexOf('=') + 1),\n"
    "          );\n"
    "  }\n"
    "  return attributes;\n"
    "}\n"
    "\n"
    "String _dartStringLiteral(String value) {\n"
    "  final escaped = value\n"
    "      .replaceAll(r'\\', r'\\\\')\n"
    "      .replaceAll(\"'\", r\"\\'\")\n"
    "      .replaceAll(r'\$', r'\\\$')\n"
    "      .replaceAll('\\n', r'\\n')\n"
    "      .replaceAll('\\r', r'\\r');\n"
    "  return \"'\$escaped'\";\n"
    "}\n"
    "\n"
    "// lib/src/generator.dart\n"
    "final _classNamePattern = RegExp(r'^[A-Za-z][A-Za-z0-9]*\$');\n"
    "final _wordSeparatorPattern = RegExp(r'[^A-Za-z0-9]+');\n"
    "final _memberNamePattern = RegExp(r'^[a-z][A-Za-z0-9]*\$');\n"
    "\n"
    "const _fragmentSource = r'''\n"
    "/// Composable HTML returned by every fragment function; render it with [toHtml].\n"
    "final class Fragment {\n"
    "  const Fragment._(this._render);\n"
    "\n"
    "  final void Function(StringBuffer) _render;\n"
    "\n"
    "  String toHtml() {\n"
    "    final out = StringBuffer();\n"
    "    _render(out);\n"
    "    return out.toString();\n"
    "  }\n"
    "}\n"
    "\n"
    "/// Writes fragments as HTML, iterables item by item, and every other non-null\n"
    "/// value as escaped text.\n"
    "void _\$write(StringBuffer out, Object? value) {\n"
    "  if (value is Fragment) {\n"
    "    value._render(out);\n"
    "  } else if (value is Iterable) {\n"
    "    for (final item in value) {\n"
    "      _\$write(out, item);\n"
    "    }\n"
    "  } else if (value != null) {\n"
    "    _\$writeEscaped(out, value.toString());\n"
    "  }\n"
    "}\n"
    "\n"
    "// Names an HTML parser reads as one attribute name.\n"
    "final _\$attributeNamePattern = RegExp('^[^\\\\s\"\\'<>/=\\\\x00-\\\\x1F\\\\x7F]+\\\$');\n"
    "\n"
    "/// Writes each entry of [attributes] as ` name=\"value\"`, failing on names\n"
    "/// that are not valid HTML or already in [writtenNames]: the tag's names so\n"
    "/// far, mapped to whether a map wrote them, which it adds to.\n"
    "void _\$writeAttributes(\n"
    "  StringBuffer out,\n"
    "  Map<String, String>? attributes,\n"
    "  Map<String, bool> writtenNames,\n"
    ") {\n"
    "  if (attributes == null) return;\n"
    "  for (final MapEntry(key: name, :value) in attributes.entries) {\n"
    "    if (!_\$attributeNamePattern.hasMatch(name)) {\n"
    "      throw ArgumentError.value(\n"
    "        name,\n"
    "        'attributes',\n"
    "        'is not a valid HTML attribute name',\n"
    "      );\n"
    "    }\n"
    "    if (writtenNames.containsKey(name.toLowerCase())) {\n"
    "      throw ArgumentError.value(name, 'attributes', _\$duplicateAttribute);\n"
    "    }\n"
    "    writtenNames[name.toLowerCase()] = true;\n"
    "    out\n"
    "      ..write(' ')\n"
    "      ..write(name)\n"
    "      ..write('=\"');\n"
    "    _\$writeEscaped(out, value);\n"
    "    out.write('\"');\n"
    "  }\n"
    "}\n"
    "\n"
    "/// Adds a conditional attribute that renders to [writtenNames], failing\n"
    "/// when a map already wrote it; conditional ones may share a name.\n"
    "void _\$addConditionalAttributeName(\n"
    "  Map<String, bool> writtenNames,\n"
    "  String name,\n"
    ") {\n"
    "  if (writtenNames[name] ?? false) {\n"
    "    throw ArgumentError.value(name, 'attributes', _\$duplicateAttribute);\n"
    "  }\n"
    "  writtenNames[name] = false;\n"
    "}\n"
    "\n"
    "const _\$duplicateAttribute =\n"
    "    'is already an attribute of this tag and browsers keep only the first; '\n"
    "    'compute one value in Dart and pass it in';\n"
    "\n"
    "/// Writes [text] with &, <, >, \" and ' replaced by the same entities as\n"
    "/// dart:convert's HtmlEscape, which is several times slower.\n"
    "void _\$writeEscaped(StringBuffer out, String text) {\n"
    "  var unwrittenStart = 0;\n"
    "  for (var index = 0; index < text.length; index++) {\n"
    "    final entity = switch (text.codeUnitAt(index)) {\n"
    "      0x26 => '&amp;',\n"
    "      0x3C => '&lt;',\n"
    "      0x3E => '&gt;',\n"
    "      0x22 => '&quot;',\n"
    "      0x27 => '&#39;',\n"
    "      _ => null,\n"
    "    };\n"
    "    if (entity == null) continue;\n"
    "    out\n"
    "      ..write(text.substring(unwrittenStart, index))\n"
    "      ..write(entity);\n"
    "    unwrittenStart = index + 1;\n"
    "  }\n"
    "  out.write(unwrittenStart == 0 ? text : text.substring(unwrittenStart));\n"
    "}\n"
    "''';\n"
    "\n"
    "/// First line of every generated file; abs only overwrites files that\n"
    "/// start with it.\n"
    "const generatedFileHeader =\n"
    "    '// GENERATED by abs (Absurd Templates). DO NOT EDIT.';\n"
    "\n"
    "final class _Namespace {\n"
    "  _Namespace(this.className, this.accessPath);\n"
    "\n"
    "  final String className;\n"
    "\n"
    "  /// How Dart code reaches this namespace, such as `Html.pages`.\n"
    "  final String accessPath;\n"
    "  final sourcePathByMemberName = <String, String>{};\n"
    "  final templatePathByMethodName = <String, String>{};\n"
    "  final compiledTemplateByMethodName = <String, CompiledTemplate>{};\n"
    "  final namespaceByGetterName = <String, _Namespace>{};\n"
    "}\n"
    "\n"
    "/// Generates the self-contained Dart library for all templates.\n"
    "///\n"
    "/// [templateSourceByPath] keys are `/`-separated paths relative to\n"
    "/// [templateDirectory], such as `pages/admin/dashboard.html`.\n"
    "/// [templateDirectory] only prefixes paths in diagnostics and source markers.\n"
    "///\n"
    "/// Throws a [Diagnostic] on invalid templates, naming conflicts or templates\n"
    "/// that render each other in a cycle.\n"
    "String generateDartLibrary({\n"
    "  required Map<String, String> templateSourceByPath,\n"
    "  required String className,\n"
    "  String templateDirectory = '',\n"
    "}) {\n"
    "  final root = _buildNamespaceTree(\n"
    "    templateSourceByPath.keys,\n"
    "    className,\n"
    "    templateDirectory,\n"
    "  );\n"
    "  final accessPathByTemplatePath = _accessPathByTemplatePath(root);\n"
    "  final renderedFragmentsByTemplatePath = <String, List<RenderedFragment>>{};\n"
    "  void compileNamespace(_Namespace namespace) {\n"
    "    for (final MapEntry(key: methodName, value: templatePath)\n"
    "        in namespace.templatePathByMethodName.entries) {\n"
    "      final compiled = compileTemplate(\n"
    "        templateSourceByPath[templatePath]!,\n"
    "        displayTemplatePath(templateDirectory, templatePath),\n"
    "        accessPathByTemplatePath: accessPathByTemplatePath,\n"
    "      );\n"
    "      namespace.compiledTemplateByMethodName[methodName] = compiled;\n"
    "      renderedFragmentsByTemplatePath[templatePath] =\n"
    "          compiled.renderedFragments;\n"
    "    }\n"
    "    namespace.namespaceByGetterName.values.forEach(compileNamespace);\n"
    "  }\n"
    "\n"
    "  compileNamespace(root);\n"
    "  _rejectFragmentCycles(renderedFragmentsByTemplatePath, templateDirectory);\n"
    "\n"
    "  final output = StringBuffer()\n"
    "    ..writeln(generatedFileHeader)\n"
    "    // The helpers go unused when no template writes a value.\n"
    "    ..writeln('// ignore_for_file: type=lint, unused_element')\n"
    "    ..writeln();\n"
    "  _writeNamespace(output, root, isRoot: true);\n"
    "  output.write(_fragmentSource);\n"
    "  return output.toString();\n"
    "}\n"
    "\n"
    "/// Maps each of [templatePaths] to the Dart expression that calls it, such\n"
    "/// as `Html.ui.label`, without compiling any template.\n"
    "///\n"
    "/// Throws a [Diagnostic] when they cannot all become distinct Dart members.\n"
    "Map<String, String> templateAccessPaths({\n"
    "  required Iterable<String> templatePaths,\n"
    "  required String className,\n"
    "  String templateDirectory = '',\n"
    "}) => _accessPathByTemplatePath(\n"
    "  _buildNamespaceTree(templatePaths, className, templateDirectory),\n"
    ");\n"
    "\n"
    "Map<String, String> _accessPathByTemplatePath(_Namespace root) {\n"
    "  final accessPathByTemplatePath = <String, String>{};\n"
    "  void collect(_Namespace namespace) {\n"
    "    for (final MapEntry(key: methodName, value: templatePath)\n"
    "        in namespace.templatePathByMethodName.entries) {\n"
    "      accessPathByTemplatePath[templatePath] =\n"
    "          '\${namespace.accessPath}.\$methodName';\n"
    "    }\n"
    "    namespace.namespaceByGetterName.values.forEach(collect);\n"
    "  }\n"
    "\n"
    "  collect(root);\n"
    "  return accessPathByTemplatePath;\n"
    "}\n"
    "\n"
    "/// Throws a [Diagnostic] at the `<x-fragment>` that closes the first cycle\n"
    "/// found, since rendering any template in it would never end.\n"
    "void _rejectFragmentCycles(\n"
    "  Map<String, List<RenderedFragment>> renderedFragmentsByTemplatePath,\n"
    "  String templateDirectory,\n"
    ") {\n"
    "  final finishedTemplatePaths = <String>{};\n"
    "  final templatePathsBeingVisited = <String>[];\n"
    "  void visit(String templatePath) {\n"
    "    if (finishedTemplatePaths.contains(templatePath)) return;\n"
    "    templatePathsBeingVisited.add(templatePath);\n"
    "    for (final rendered\n"
    "        in renderedFragmentsByTemplatePath[templatePath] ?? const []) {\n"
    "      final cycleStart = templatePathsBeingVisited.indexOf(\n"
    "        rendered.templatePath,\n"
    "      );\n"
    "      if (cycleStart != -1) {\n"
    "        final cycle = [\n"
    "          ...templatePathsBeingVisited.sublist(cycleStart),\n"
    "          rendered.templatePath,\n"
    "        ].map((path) => '/\$path').join(' -> ');\n"
    "        throw Diagnostic(\n"
    "          'templates cannot render themselves, directly or through other '\n"
    "          'templates; this <x-fragment> closes the cycle \$cycle',\n"
    "          path: displayTemplatePath(templateDirectory, templatePath),\n"
    "          line: rendered.line,\n"
    "          column: rendered.column,\n"
    "          lineText: rendered.lineText,\n"
    "        );\n"
    "      }\n"
    "      visit(rendered.templatePath);\n"
    "    }\n"
    "    templatePathsBeingVisited.removeLast();\n"
    "    finishedTemplatePaths.add(templatePath);\n"
    "  }\n"
    "\n"
    "  (renderedFragmentsByTemplatePath.keys.toList()..sort()).forEach(visit);\n"
    "}\n"
    "\n"
    "/// The path of a template as shown to users, such as\n"
    "/// `fragments/pages/user.html`.\n"
    "String displayTemplatePath(String templateDirectory, String templatePath) =>\n"
    "    templateDirectory.isEmpty\n"
    "    ? templatePath\n"
    "    : '\$templateDirectory/\$templatePath';\n"
    "\n"
    "_Namespace _buildNamespaceTree(\n"
    "  Iterable<String> templatePaths,\n"
    "  String className,\n"
    "  String templateDirectory,\n"
    ") {\n"
    "  if (!_classNamePattern.hasMatch(className) || className == 'Fragment') {\n"
    "    throw Diagnostic(\n"
    "      'class name \"\$className\" is invalid; use letters and digits, start '\n"
    "      'with a letter, and do not use \"Fragment\"',\n"
    "    );\n"
    "  }\n"
    "  final root = _Namespace(className, className);\n"
    "\n"
    "  for (final templatePath in templatePaths.toList()..sort()) {\n"
    "    final segments = templatePath.split('/');\n"
    "    var namespace = root;\n"
    "    for (var depth = 0; depth < segments.length - 1; depth++) {\n"
    "      final directoryPath = displayTemplatePath(\n"
    "        templateDirectory,\n"
    "        '\${segments.sublist(0, depth + 1).join('/')}/',\n"
    "      );\n"
    "      final getterName = _memberName(segments[depth], directoryPath);\n"
    "      _claimMemberName(namespace, getterName, directoryPath);\n"
    "      namespace = namespace.namespaceByGetterName.putIfAbsent(\n"
    "        getterName,\n"
    "        // Nested namespace classes stay private: only the root class is API.\n"
    "        () => _Namespace(\n"
    "          '\${namespace == root ? '_' : ''}\${namespace.className}\\\$\$getterName',\n"
    "          '\${namespace.accessPath}.\$getterName',\n"
    "        ),\n"
    "      );\n"
    "    }\n"
    "    final fileName = segments.last;\n"
    "    final methodName = _memberName(\n"
    "      fileName.substring(0, fileName.length - '.html'.length),\n"
    "      displayTemplatePath(templateDirectory, templatePath),\n"
    "    );\n"
    "    _claimMemberName(\n"
    "      namespace,\n"
    "      methodName,\n"
    "      displayTemplatePath(templateDirectory, templatePath),\n"
    "    );\n"
    "    namespace.templatePathByMethodName[methodName] = templatePath;\n"
    "  }\n"
    "  return root;\n"
    "}\n"
    "\n"
    "/// Records [memberName] in [namespace], rejecting names already taken by a\n"
    "/// different file or directory.\n"
    "void _claimMemberName(\n"
    "  _Namespace namespace,\n"
    "  String memberName,\n"
    "  String sourcePath,\n"
    ") {\n"
    "  final existingSourcePath = namespace.sourcePathByMemberName[memberName];\n"
    "  if (existingSourcePath != null && existingSourcePath != sourcePath) {\n"
    "    throw Diagnostic(\n"
    "      '\$existingSourcePath and \$sourcePath would both become '\n"
    "      '\${namespace.accessPath}.\$memberName; rename one of them',\n"
    "      path: sourcePath,\n"
    "    );\n"
    "  }\n"
    "  namespace.sourcePathByMemberName[memberName] = sourcePath;\n"
    "}\n"
    "\n"
    "/// Converts a file or directory name such as `user-page` into `userPage`.\n"
    "String _memberName(String name, String sourcePath) {\n"
    "  final words = name.split(_wordSeparatorPattern).where((w) => w.isNotEmpty);\n"
    "  final memberName = [\n"
    "    for (final (index, word) in words.indexed)\n"
    "      (index == 0 ? word[0].toLowerCase() : word[0].toUpperCase()) +\n"
    "          word.substring(1),\n"
    "  ].join();\n"
    "  if (!_memberNamePattern.hasMatch(memberName) ||\n"
    "      reservedDartNames.contains(memberName)) {\n"
    "    throw Diagnostic(\n"
    "      '\"\$name\" cannot become a Dart name (it converts to \"\$memberName\"); '\n"
    "      'file and directory names must start with a letter and must not be '\n"
    "      'Dart reserved words such as \"class\" or \"switch\"',\n"
    "      path: sourcePath,\n"
    "    );\n"
    "  }\n"
    "  return memberName;\n"
    "}\n"
    "\n"
    "void _writeNamespace(\n"
    "  StringBuffer output,\n"
    "  _Namespace namespace, {\n"
    "  required bool isRoot,\n"
    "}) {\n"
    "  final memberPrefix = isRoot ? 'static ' : '';\n"
    "  final members = [\n"
    "    if (!isRoot) '  const \${namespace.className}();',\n"
    "    for (final MapEntry(key: methodName, value: template)\n"
    "        in namespace.compiledTemplateByMethodName.entries)\n"
    "      '  \${memberPrefix}Fragment \$methodName(\${template.parameters}) =>\\n'\n"
    "          '      Fragment._((\\\$out) {\\n'\n"
    "          '    \${template.body.trimRight().replaceAll('\\n', '\\n    ')}\\n'\n"
    "          '  });',\n"
    "    for (final MapEntry(key: getterName, value: child)\n"
    "        in namespace.namespaceByGetterName.entries)\n"
    "      isRoot\n"
    "          ? '  static const \$getterName = \${child.className}();'\n"
    "          : '  \${child.className} get \$getterName => const \${child.className}();',\n"
    "  ];\n"
    "  output\n"
    "    ..writeln(\n"
    "      '\${isRoot ? 'abstract final' : 'final'} class \${namespace.className} {',\n"
    "    )\n"
    "    ..writeln(members.join('\\n\\n'))\n"
    "    ..writeln('}')\n"
    "    ..writeln();\n"
    "\n"
    "  for (final child in namespace.namespaceByGetterName.values) {\n"
    "    _writeNamespace(output, child, isRoot: false);\n"
    "  }\n"
    "}\n"
    "\n"
    "// lib/src/check.dart\n"
    "final _sourceMarkerPattern = RegExp(r'// (.+\\.html):(\\d+):(\\d+)\$');\n"
    "\n"
    "/// Checks the templates at [checkedTemplatePaths] for syntax errors and Dart\n"
    "/// errors (types, undefined names...), and all of [templateSourceByPath] for\n"
    "/// naming conflicts. Writes nothing; returns every problem found.\n"
    "///\n"
    "/// Paths are relative to [templateDirectory], as in [generateDartLibrary].\n"
    "Future<List<Diagnostic>> checkTemplates({\n"
    "  required Map<String, String> templateSourceByPath,\n"
    "  required Iterable<String> checkedTemplatePaths,\n"
    "  required String className,\n"
    "  String templateDirectory = '',\n"
    "}) async {\n"
    "  final diagnostics = <Diagnostic>[];\n"
    "  Map<String, String>? accessPathByTemplatePath;\n"
    "  try {\n"
    "    accessPathByTemplatePath = templateAccessPaths(\n"
    "      templatePaths: templateSourceByPath.keys,\n"
    "      className: className,\n"
    "      templateDirectory: templateDirectory,\n"
    "    );\n"
    "  } on Diagnostic catch (diagnostic) {\n"
    "    diagnostics.add(diagnostic);\n"
    "  }\n"
    "\n"
    "  // Templates rendered with <x-fragment> are compiled and analyzed too, or\n"
    "  // the checked templates would call functions missing from the library.\n"
    "  final templatePathsToCompile = [...checkedTemplatePaths];\n"
    "  final renderedTemplatePathsByCompilablePath = <String, List<String>>{};\n"
    "  for (var index = 0; index < templatePathsToCompile.length; index++) {\n"
    "    final templatePath = templatePathsToCompile[index];\n"
    "    try {\n"
    "      final compiled = compileTemplate(\n"
    "        templateSourceByPath[templatePath]!,\n"
    "        displayTemplatePath(templateDirectory, templatePath),\n"
    "        accessPathByTemplatePath: accessPathByTemplatePath,\n"
    "      );\n"
    "      final renderedTemplatePaths = [\n"
    "        for (final rendered in compiled.renderedFragments)\n"
    "          rendered.templatePath,\n"
    "      ];\n"
    "      renderedTemplatePathsByCompilablePath[templatePath] =\n"
    "          renderedTemplatePaths;\n"
    "      for (final renderedTemplatePath in renderedTemplatePaths) {\n"
    "        // Missing ones are reported once naming conflicts are fixed, since\n"
    "        // only then are <x-fragment> paths resolved.\n"
    "        if (templateSourceByPath.containsKey(renderedTemplatePath) &&\n"
    "            !templatePathsToCompile.contains(renderedTemplatePath)) {\n"
    "          templatePathsToCompile.add(renderedTemplatePath);\n"
    "        }\n"
    "      }\n"
    "    } on Diagnostic catch (diagnostic) {\n"
    "      diagnostics.add(diagnostic);\n"
    "    }\n"
    "  }\n"
    "  // A template that renders one with syntax errors cannot be analyzed.\n"
    "  int compilableCountBefore;\n"
    "  do {\n"
    "    compilableCountBefore = renderedTemplatePathsByCompilablePath.length;\n"
    "    renderedTemplatePathsByCompilablePath.removeWhere(\n"
    "      (_, renderedTemplatePaths) => !renderedTemplatePaths.every(\n"
    "        renderedTemplatePathsByCompilablePath.containsKey,\n"
    "      ),\n"
    "    );\n"
    "  } while (renderedTemplatePathsByCompilablePath.length <\n"
    "      compilableCountBefore);\n"
    "\n"
    "  if (accessPathByTemplatePath != null &&\n"
    "      renderedTemplatePathsByCompilablePath.isNotEmpty) {\n"
    "    final compilableSourceByPath = {\n"
    "      for (final templatePath in renderedTemplatePathsByCompilablePath.keys)\n"
    "        templatePath: templateSourceByPath[templatePath]!,\n"
    "    };\n"
    "    final String library;\n"
    "    try {\n"
    "      library = generateDartLibrary(\n"
    "        templateSourceByPath: compilableSourceByPath,\n"
    "        className: className,\n"
    "        templateDirectory: templateDirectory,\n"
    "      );\n"
    "    } on Diagnostic catch (diagnostic) {\n"
    "      return [...diagnostics, diagnostic];\n"
    "    }\n"
    "    diagnostics.addAll(\n"
    "      await _analyzeGeneratedLibrary(library, {\n"
    "        for (final MapEntry(key: templatePath, value: source)\n"
    "            in compilableSourceByPath.entries)\n"
    "          displayTemplatePath(templateDirectory, templatePath): source,\n"
    "      }),\n"
    "    );\n"
    "  }\n"
    "  return diagnostics;\n"
    "}\n"
    "\n"
    "/// Runs `dart analyze` on [library] and maps each error and warning back to\n"
    "/// the template line named by the nearest source marker.\n"
    "Future<List<Diagnostic>> _analyzeGeneratedLibrary(\n"
    "  String library,\n"
    "  Map<String, String> templateSourceByDisplayPath,\n"
    ") async {\n"
    "  final directory = await Directory.systemTemp.createTemp('abs_check_');\n"
    "  try {\n"
    "    final libraryFile = File('\${directory.path}/check.dart')\n"
    "      ..writeAsStringSync(library);\n"
    "    final ProcessResult result;\n"
    "    try {\n"
    "      result = await Process.run('dart', [\n"
    "        'analyze',\n"
    "        '--format=machine',\n"
    "        libraryFile.path,\n"
    "      ]);\n"
    "    } on ProcessException catch (error) {\n"
    "      return [\n"
    "        Diagnostic(\n"
    "          'could not run \"dart analyze\" to type-check templates '\n"
    "          '(\${error.message}); make sure \"dart\" is on your PATH',\n"
    "        ),\n"
    "      ];\n"
    "    }\n"
    "    // dart analyze exits with 0-3 when it ran; anything else means it failed.\n"
    "    if (result.exitCode > 3) {\n"
    "      return [\n"
    "        Diagnostic(\n"
    "          '\"dart analyze\" failed with exit code \${result.exitCode}, so Dart '\n"
    "                  'errors were not checked:\\n\${result.stderr}\${result.stdout}'\n"
    "              .trimRight(),\n"
    "        ),\n"
    "      ];\n"
    "    }\n"
    "    final generatedLines = library.split('\\n');\n"
    "    return [\n"
    "      for (final outputLine in '\${result.stdout}\\n\${result.stderr}'.split('\\n'))\n"
    "        if (outputLine.split('|') case [\n"
    "          final severity && ('ERROR' || 'WARNING'),\n"
    "          _,\n"
    "          _,\n"
    "          _,\n"
    "          final generatedLineNumber,\n"
    "          _,\n"
    "          _,\n"
    "          ...final messageParts,\n"
    "        ])\n"
    "          _mapToTemplate(\n"
    "            message: messageParts.join('|'),\n"
    "            severity: severity.toLowerCase(),\n"
    "            generatedLineNumber: int.parse(generatedLineNumber),\n"
    "            generatedLines: generatedLines,\n"
    "            templateSourceByDisplayPath: templateSourceByDisplayPath,\n"
    "          ),\n"
    "    ];\n"
    "  } finally {\n"
    "    await directory.delete(recursive: true);\n"
    "  }\n"
    "}\n"
    "\n"
    "Diagnostic _mapToTemplate({\n"
    "  required String message,\n"
    "  required String severity,\n"
    "  required int generatedLineNumber,\n"
    "  required List<String> generatedLines,\n"
    "  required Map<String, String> templateSourceByDisplayPath,\n"
    "}) {\n"
    "  // A statement's marker sits on its last line, at or below the error.\n"
    "  for (\n"
    "    var index = generatedLineNumber - 1;\n"
    "    index < generatedLines.length;\n"
    "    index++\n"
    "  ) {\n"
    "    final marker = _sourceMarkerPattern.firstMatch(generatedLines[index]);\n"
    "    if (marker == null) continue;\n"
    "    final path = marker[1]!;\n"
    "    final line = int.parse(marker[2]!);\n"
    "    return Diagnostic(\n"
    "      message,\n"
    "      severity: severity,\n"
    "      path: path,\n"
    "      line: line,\n"
    "      column: int.parse(marker[3]!),\n"
    "      lineText: templateSourceByDisplayPath[path]\n"
    "          ?.split('\\n')\n"
    "          .elementAtOrNull(line - 1)\n"
    "          ?.trimRight(),\n"
    "    );\n"
    "  }\n"
    "  return Diagnostic(\n"
    "    '\$message (at line \$generatedLineNumber of the generated code, outside '\n"
    "    'any template; this is likely a bug in abs)',\n"
    "    severity: severity,\n"
    "  );\n"
    "}\n"
    "\n"
    "// lib/src/cli.dart\n"
    "const _configFileName = 'abs.yaml';\n"
    "const _configKeys = {'input', 'output', 'class'};\n"
    "\n"
    "/// A top-level `key: value` line of abs.yaml: the value is double-quoted,\n"
    "/// single-quoted or plain text, optionally followed by a `# comment`.\n"
    "final _configLinePattern = RegExp(\n"
    "  r\"\"\"^([A-Za-z_][\\w-]*):\"\"\"\n"
    "  r\"\"\"(?:[ \\t]+(?:\"([^\"]*)\"|'([^']*)'|([^\\s#\"'\\[\\]{}&*!|>%@`](?:[^#]|(?<=\\S)#)*?)))?\"\"\"\n"
    "  r\"\"\"(?:[ \\t]+#.*)?[ \\t]*\$\"\"\",\n"
    ");\n"
    "\n"
    "/// Version of abs; keep it equal to the version in pubspec.yaml.\n"
    "const absVersion = '0.1.0';\n"
    "\n"
    "/// The help text; [canVendor] is false in a vendored copy.\n"
    "String _usage({required bool canVendor}) =>\n"
    "    '''\n"
    "Absurd Templates \$absVersion: compiles HTML templates into one self-contained Dart file.\n"
    "\n"
    "Usage:\n"
    "  abs                        Generate the output file configured in abs.yaml.\n"
    "  abs check [file.html ...]  Check templates without writing anything: syntax,\n"
    "                             naming conflicts and Dart errors (types, undefined\n"
    "                             names). Checks every template when no file is\n"
    "                             given. Exits with 1 when there are errors.\n"
    "  abs init                   Create a commented abs.yaml in this directory.\n"
    "\${canVendor ? _vendorUsage : ''}  abs version                Print the version of abs.\n"
    "  abs help                   Show this message.\n"
    "\n"
    "abs.yaml, in the directory where abs runs:\n"
    "  input: fragments                 # directory scanned for .html templates\n"
    "  output: lib/generated/html.dart  # file to generate\n"
    "  class: Html                      # optional, defaults to Fragments\n"
    "''';\n"
    "\n"
    "const _initialConfig = '''\n"
    "# Absurd Templates configuration. abs reads this file from the directory it\n"
    "# runs in.\n"
    "#\n"
    "#   abs                    generate the Dart file below from the templates\n"
    "#   abs check [file.html]  check templates for errors without writing anything\n"
    "#   abs help               list every command\n"
    "\n"
    "# Required. Directory scanned recursively for .html templates. Each file\n"
    "# becomes a method and each subdirectory a namespace, in camelCase:\n"
    "#   fragments/header.html           -> Fragments.header()\n"
    "#   fragments/pages/user-page.html  -> Fragments.pages.userPage(...)\n"
    "input: fragments\n"
    "\n"
    "# Required. The one self-contained Dart file to generate, including the\n"
    "# Fragment type, so no runtime package is needed. abs only overwrites files\n"
    "# it generated itself.\n"
    "output: lib/generated/html.dart\n"
    "\n"
    "# Optional. Name of the generated entry class. Defaults to Fragments.\n"
    "# class: Html\n"
    "''';\n"
    "\n"
    "typedef _Project = ({\n"
    "  String inputDirectory,\n"
    "  String outputFile,\n"
    "  String className,\n"
    "  Map<String, String> templateSourceByPath,\n"
    "});\n"
    "\n"
    "const _vendorUsage = '''\n"
    "  abs vendor [file.dart]     Copy abs into this project as one Dart file with\n"
    "                             no dependencies, tool/abs.dart by default; run it\n"
    "                             with \"dart run tool/abs.dart\". Run it again with\n"
    "                             a newer abs to update the copy.\n"
    "''';\n"
    "\n"
    "/// Runs the abs command line with [arguments]. [vendor] runs `abs vendor`;\n"
    "/// a vendored copy has none.\n"
    "Future<void> runAbs(\n"
    "  List<String> arguments, {\n"
    "  void Function(List<String> arguments)? vendor,\n"
    "}) async {\n"
    "  try {\n"
    "    switch (arguments) {\n"
    "      case []:\n"
    "        _generate(_loadProject());\n"
    "      case ['check', ...final files]:\n"
    "        exitCode = await _check(_loadProject(), files);\n"
    "      case ['init']:\n"
    "        _init();\n"
    "      case ['vendor', ...final vendorArguments]:\n"
    "        if (vendor == null) {\n"
    "          throw Diagnostic(\n"
    "            'this is a vendored copy of abs \$absVersion, which cannot vendor '\n"
    "            'itself; to update it, run \"abs vendor\" with an installed abs',\n"
    "          );\n"
    "        }\n"
    "        vendor(vendorArguments);\n"
    "      case ['version' || '--version']:\n"
    "        stdout.writeln(absVersion);\n"
    "      case ['help' || '--help' || '-h']:\n"
    "        stdout.write(_usage(canVendor: vendor != null));\n"
    "      default:\n"
    "        throw Diagnostic(\n"
    "          'unknown command \"abs \${arguments.join(' ')}\"; run \"abs help\"',\n"
    "        );\n"
    "    }\n"
    "  } on Diagnostic catch (diagnostic) {\n"
    "    stderr.writeln(diagnostic.format());\n"
    "    exitCode = 1;\n"
    "  }\n"
    "}\n"
    "\n"
    "void _init() {\n"
    "  final configFile = File(_configFileName);\n"
    "  if (configFile.existsSync()) {\n"
    "    throw Diagnostic(\n"
    "      '\$_configFileName already exists in \${Directory.current.path}; '\n"
    "      'abs init does not overwrite it',\n"
    "      path: _configFileName,\n"
    "    );\n"
    "  }\n"
    "  configFile.writeAsStringSync(_initialConfig);\n"
    "  stdout.writeln(\n"
    "    'abs: created \$_configFileName; put your .html templates in fragments/ '\n"
    "    'and run abs',\n"
    "  );\n"
    "}\n"
    "\n"
    "void _generate(_Project project) {\n"
    "  final stopwatch = Stopwatch()..start();\n"
    "  final String library;\n"
    "  try {\n"
    "    library = generateDartLibrary(\n"
    "      templateSourceByPath: project.templateSourceByPath,\n"
    "      className: project.className,\n"
    "      templateDirectory: project.inputDirectory,\n"
    "    );\n"
    "  } on Diagnostic catch (diagnostic) {\n"
    "    stderr\n"
    "      ..writeln(diagnostic.format())\n"
    "      ..writeln()\n"
    "      ..writeln(\n"
    "        'abs: nothing was generated; run \"abs check\" to list every problem',\n"
    "      );\n"
    "    exitCode = 1;\n"
    "    return;\n"
    "  }\n"
    "  final outputFile = File(project.outputFile);\n"
    "  if (outputFile.existsSync() && !_startsWithGeneratedHeader(outputFile)) {\n"
    "    throw Diagnostic(\n"
    "      '\${project.outputFile} already exists and was not generated by abs, so '\n"
    "      'abs will not overwrite it; point \"output\" in \$_configFileName at '\n"
    "      'another file, or delete this one if it really should be replaced',\n"
    "      path: project.outputFile,\n"
    "    );\n"
    "  }\n"
    "  // Leaving an unchanged file alone keeps watchers from rebuilding.\n"
    "  final isUnchanged =\n"
    "      outputFile.existsSync() && outputFile.readAsStringSync() == library;\n"
    "  if (!isUnchanged) {\n"
    "    outputFile\n"
    "      ..createSync(recursive: true)\n"
    "      ..writeAsStringSync(library);\n"
    "  }\n"
    "  stdout.writeln(\n"
    "    'abs: \${isUnchanged ? 'unchanged' : 'generated'} \${project.outputFile} '\n"
    "    'from \${project.templateSourceByPath.length} templates in '\n"
    "    '\${stopwatch.elapsedMilliseconds}ms',\n"
    "  );\n"
    "}\n"
    "\n"
    "bool _startsWithGeneratedHeader(File file) {\n"
    "  final handle = file.openSync();\n"
    "  try {\n"
    "    // Bytes, not text, so a binary file cannot fail to decode.\n"
    "    final header = handle.readSync(generatedFileHeader.length);\n"
    "    return utf8.decode(header, allowMalformed: true) == generatedFileHeader;\n"
    "  } finally {\n"
    "    handle.closeSync();\n"
    "  }\n"
    "}\n"
    "\n"
    "Future<int> _check(_Project project, List<String> files) async {\n"
    "  final checkedTemplatePaths = files.isEmpty\n"
    "      ? project.templateSourceByPath.keys.toList()\n"
    "      : {for (final file in files) _templatePathOf(project, file)}.toList();\n"
    "  final diagnostics = await checkTemplates(\n"
    "    templateSourceByPath: project.templateSourceByPath,\n"
    "    checkedTemplatePaths: checkedTemplatePaths,\n"
    "    className: project.className,\n"
    "    templateDirectory: project.inputDirectory,\n"
    "  );\n"
    "  for (final diagnostic in diagnostics) {\n"
    "    stdout\n"
    "      ..writeln(diagnostic.format())\n"
    "      ..writeln();\n"
    "  }\n"
    "  final errorCount = diagnostics.where((d) => d.isError).length;\n"
    "  final warningCount = diagnostics.length - errorCount;\n"
    "  final templates = _plural(checkedTemplatePaths.length, 'template');\n"
    "  stdout.writeln(\n"
    "    diagnostics.isEmpty\n"
    "        ? 'abs check: \$templates OK'\n"
    "        : 'abs check: \${_plural(errorCount, 'error')} and '\n"
    "              '\${_plural(warningCount, 'warning')} in \$templates',\n"
    "  );\n"
    "  return errorCount == 0 ? 0 : 1;\n"
    "}\n"
    "\n"
    "String _plural(int count, String noun) =>\n"
    "    '\$count \$noun\${count == 1 ? '' : 's'}';\n"
    "\n"
    "/// Converts a template file path given on the command line into its path\n"
    "/// relative to the input directory.\n"
    "String _templatePathOf(_Project project, String file) {\n"
    "  if (!file.endsWith('.html')) {\n"
    "    throw Diagnostic('\"\$file\" is not a template: templates end with .html');\n"
    "  }\n"
    "  final absoluteInputDirectory = Directory.current.uri\n"
    "      .resolveUri(Uri.directory(project.inputDirectory))\n"
    "      .toFilePath();\n"
    "  final absoluteFile = Directory.current.uri\n"
    "      .resolveUri(Uri.file(file))\n"
    "      .toFilePath();\n"
    "  if (!absoluteFile.startsWith(absoluteInputDirectory)) {\n"
    "    throw Diagnostic(\n"
    "      '\"\$file\" is not inside the input directory \"\${project.inputDirectory}\" '\n"
    "      'configured in \$_configFileName',\n"
    "    );\n"
    "  }\n"
    "  final templatePath = _toTemplatePath(\n"
    "    absoluteFile.substring(absoluteInputDirectory.length),\n"
    "  );\n"
    "  if (!project.templateSourceByPath.containsKey(templatePath)) {\n"
    "    throw Diagnostic('\"\$file\" does not exist');\n"
    "  }\n"
    "  return templatePath;\n"
    "}\n"
    "\n"
    "_Project _loadProject() {\n"
    "  final configFile = File(_configFileName);\n"
    "  if (!configFile.existsSync()) {\n"
    "    throw Diagnostic(\n"
    "      '\$_configFileName not found in \${Directory.current.path}; run abs '\n"
    "      'from the directory that contains it, or create it (see \"abs help\")',\n"
    "    );\n"
    "  }\n"
    "  final configLines = configFile.readAsStringSync().split('\\n');\n"
    "\n"
    "  Diagnostic configError(String message, {int lineIndex = 0}) => Diagnostic(\n"
    "    message,\n"
    "    path: _configFileName,\n"
    "    line: lineIndex + 1,\n"
    "    column: 1,\n"
    "    lineText: configLines[lineIndex].trimRight(),\n"
    "  );\n"
    "\n"
    "  final valueByKey = <String, ({String value, int lineIndex})>{};\n"
    "  for (final (lineIndex, line) in configLines.indexed) {\n"
    "    final trimmedLine = line.trim();\n"
    "    if (trimmedLine.isEmpty || trimmedLine.startsWith('#')) continue;\n"
    "    final match =\n"
    "        _configLinePattern.firstMatch(line.trimRight()) ??\n"
    "        (throw configError(\n"
    "          'expected a \"key: value\" line; \$_configFileName only holds '\n"
    "          'top-level keys with plain or quoted text values',\n"
    "          lineIndex: lineIndex,\n"
    "        ));\n"
    "    final key = match[1]!;\n"
    "    if (!_configKeys.contains(key)) {\n"
    "      throw configError(\n"
    "        'unknown key \"\$key\"; supported keys: \${_configKeys.join(', ')}',\n"
    "        lineIndex: lineIndex,\n"
    "      );\n"
    "    }\n"
    "    if (valueByKey.containsKey(key)) {\n"
    "      throw configError('\"\$key\" is set twice', lineIndex: lineIndex);\n"
    "    }\n"
    "    valueByKey[key] = (\n"
    "      value: match[2] ?? match[3] ?? match[4] ?? '',\n"
    "      lineIndex: lineIndex,\n"
    "    );\n"
    "  }\n"
    "\n"
    "  String stringValue(String key, {String? defaultValue}) {\n"
    "    final entry = valueByKey[key];\n"
    "    // The default only applies when the key is absent, not when it is empty.\n"
    "    final value = entry == null ? defaultValue : entry.value;\n"
    "    if (value == null || value.isEmpty) {\n"
    "      throw configError(\n"
    "        entry == null\n"
    "            ? '\"\$key\" is required (see \"abs help\")'\n"
    "            : '\"\$key\" must be a non-empty string',\n"
    "        lineIndex: entry?.lineIndex ?? 0,\n"
    "      );\n"
    "    }\n"
    "    return value;\n"
    "  }\n"
    "\n"
    "  final inputDirectory = _normalizeDirectory(stringValue('input'));\n"
    "  final outputFile = stringValue('output');\n"
    "  final className = stringValue('class', defaultValue: 'Fragments');\n"
    "  if (!Directory(inputDirectory).existsSync()) {\n"
    "    throw configError(\n"
    "      'input directory \"\$inputDirectory\" does not exist',\n"
    "      lineIndex: valueByKey['input']!.lineIndex,\n"
    "    );\n"
    "  }\n"
    "  return (\n"
    "    inputDirectory: inputDirectory,\n"
    "    outputFile: outputFile,\n"
    "    className: className,\n"
    "    templateSourceByPath: {\n"
    "      for (final entity in Directory(inputDirectory).listSync(recursive: true))\n"
    "        if (entity is File && entity.path.endsWith('.html'))\n"
    "          _toTemplatePath(entity.path.substring(inputDirectory.length + 1)):\n"
    "              entity.readAsStringSync(),\n"
    "    },\n"
    "  );\n"
    "}\n"
    "\n"
    "/// [path] relative to the input directory, with \"/\" as separator on every\n"
    "/// platform.\n"
    "String _toTemplatePath(String path) =>\n"
    "    path.split(Platform.pathSeparator).join('/');\n"
    "\n"
    "/// [directory] without \".\" and \"..\" segments or a trailing separator, such\n"
    "/// as \"fragments\" for \"./fragments/\".\n"
    "String _normalizeDirectory(String directory) {\n"
    "  final normalized = Uri.directory(directory).normalizePath().toFilePath();\n"
    "  return normalized.length > 1 && normalized.endsWith(Platform.pathSeparator)\n"
    "      ? normalized.substring(0, normalized.length - 1)\n"
    "      : normalized;\n"
    "}\n";
